// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount < 1e30);
        amount = bound(amount, 1, 1e30);

        // Fund c through its payable fallback.
        vm.deal(address(this), amount);
        (bool s, ) = address(c).call{value: amount}("");
        assertTrue(s);
        assertTrue(address(c).balance == amount);

        // The owner (this test contract, which has no receive/payable fallback,
        // so any transfer/call of ETH to it FAILS) withdraws `amount`.
        uint256 before = address(c).balance;
        bool ok;
        try c.withdraw(amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: a successful withdraw MUST have actually transferred
        // the funds out; the mutant returns success while the balance is
        // unchanged because it ignores the failed low-level call.
        assertTrue(!ok || address(c).balance == before - amount);
    }
}
